class Queue:
    def __init__(self):
        self.stack1 = []
        self.stack2 = []
        self.front = None
        self.rear = None

    def enqueue(self, item):
        if self.rear is None:
            self.rear = 0
            self.front = 0
        self.stack1.append(item)
        self.rear += 1

    def dequeue(self):
        if self.front is None:
            return None
        if self.front == self.rear:
            self.front = None
            self.rear = None
            return self.stack1.pop()
        else:
            item = self.stack1.pop()
            self.stack2.append(item)
            self.front += 1
            return item

    def peek(self):
        if self.front is None:
            return None
        return self.stack1[self.front]

    def is_empty(self):
        return self.front is None and self.rear is None

This implementation uses two stacks to simulate a queue. The `enqueue` method adds an item to the end of the queue by appending it to the first stack. The `dequeue` method removes an item from the front of the queue by popping it from the first stack and appending it to the second stack. The `peek` method returns the item at the front of the queue without removing it. The `is_empty` method returns `True` if the queue is empty and `False` otherwise.```
